script:
(function () {
  'use strict';
  // 1031 exchange deadlines (IRC 1031(a)(3); Treas. Reg. 1.1031(k)-1(b)(2); 2025 Instructions for
  // Form 8824, lines 5 and 6):
  //   Identification deadline = closing date + 45 calendar days.
  //   Exchange deadline = the earlier of closing date + 180 calendar days and the due date (including
  //   extensions) of the return for the tax year of the sale.
  // Return due dates for calendar-year filers, in the year after the sale: April 15 (Form 1040 /
  // 1120), October 15 extended; March 15 (Form 1065 / 1120-S), September 15 extended. The nominal
  // date is used (no weekend or holiday roll-forward) to stay on the safe side; "Other due date"
  // covers fiscal years and anything else.
  // Dates are whole day numbers (days since 1970-01-01, H. Hinnant's days_from_civil) parsed from the
  // YYYY-MM-DD input string, so time zones and daylight saving can never shift a date. "Today" is
  // the viewer's local calendar date.
  // Verified (Node, scratchpad tests/g1031_lkt.test.js): closing 2026-01-15 -> 45-day 2026-03-01
  //   (Sunday), 180-day 2026-07-14 (Tuesday), April 15 2027 later, so day 180 governs;
  //   closing 2026-12-01 -> day 180 2027-05-30, April 15 2027 governs (135 days) unless extended,
  //   October 15 2027 gives the full 180; closing 2027-12-31 -> 45-day 2028-02-14 (leap year),
  //   180-day 2028-06-28; Date.UTC agrees on each; invalid or missing dates show an error.
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  var DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  var DUE = { apr: [4, 15], oct: [10, 15], mar: [3, 15], sep: [9, 15] };

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }

  function daysFromCivil(y, m, d) {
    y -= m <= 2 ? 1 : 0;
    var era = Math.floor(y / 400), yoe = y - era * 400;
    var doy = Math.floor((153 * ((m + 9) % 12) + 2) / 5) + d - 1;
    var doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
    return era * 146097 + doe - 719468;
  }
  function civilFromDays(z) {
    z += 719468;
    var era = Math.floor(z / 146097), doe = z - era * 146097;
    var yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
    var doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
    var mp = Math.floor((5 * doy + 2) / 153);
    var d = doy - Math.floor((153 * mp + 2) / 5) + 1, m = mp < 10 ? mp + 3 : mp - 9;
    return { y: yoe + era * 400 + (m <= 2 ? 1 : 0), m: m, d: d };
  }
  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || '').trim());
    if (!m) return NaN;
    var y = +m[1], mo = +m[2], d = +m[3];
    if (mo < 1 || mo > 12 || d < 1 || d > 31) return NaN;
    var z = daysFromCivil(y, mo, d), c = civilFromDays(z);
    return c.y === y && c.m === mo && c.d === d ? z : NaN;
  }
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function iso(z) { var c = civilFromDays(z); return c.y + '-' + pad(c.m) + '-' + pad(c.d); }
  function weekday(z) { return DAYS[((z % 7) + 11) % 7]; }
  function fmt(z) { var c = civilFromDays(z); return MONTHS[c.m - 1] + ' ' + c.d + ', ' + c.y; }
  function todayNum() { var t = new Date(); return daysFromCivil(t.getFullYear(), t.getMonth() + 1, t.getDate()); }
  function plural(n, w) { return n + ' ' + w + (n === 1 ? '' : 's'); }
  function fromToday(z, today) {
    var n = z - today;
    if (n === 0) return 'Today';
    return n > 0 ? plural(n, 'day') + ' from today' : plural(-n, 'day') + ' ago';
  }
  function rel(n) { return n === 0 ? 'Today' : (n > 0 ? '+' + n : '−' + (-n)); }

  function deadlines(close, dueKind, customDue) {
    var c = civilFromDays(close);
    var due = dueKind === 'custom' ? customDue : daysFromCivil(c.y + 1, DUE[dueKind][0], DUE[dueKind][1]);
    var id45 = close + 45, d180 = close + 180;
    return { id45: id45, d180: d180, due: due, end: Math.min(d180, due) };
  }

  function clear() {
    ['lktId', 'lktIdLeft', 'lktEnd', 'lktEndLeft', 'lktNote', 'lktDay180', 'lktDue', 'lktLength'].forEach(function (id) { setText(id, '–'); });
    el('lktSchedule').innerHTML = '';
  }

  function update() {
    var kind = el('lktReturn').value;
    el('lktCustomWrap').hidden = kind !== 'custom';
    var close = parseDate(el('lktClose').value);
    var custom = kind === 'custom' ? parseDate(el('lktCustom').value) : 0;
    var err = el('lktError'), msg = '';
    if (isNaN(close)) msg = 'Enter the closing date of the property you sold.';
    else if (close < daysFromCivil(1990, 1, 1) || close > daysFromCivil(2200, 12, 31)) msg = 'Enter a closing date between 1990 and 2200.';
    else if (!DUE[kind] && kind !== 'custom') msg = 'Choose a tax return due date.';
    else if (kind === 'custom' && isNaN(custom)) msg = 'Enter your tax return due date, including extensions.';
    else if (kind === 'custom' && custom <= close) msg = 'The return due date must be after the closing date.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { clear(); return; }

    var r = deadlines(close, kind, custom), today = todayNum();
    if (r.id45 > r.end) r.id45 = r.end;
    setText('lktId', fmt(r.id45));
    setText('lktIdLeft', weekday(r.id45) + ' · ' + fromToday(r.id45, today));
    setText('lktEnd', fmt(r.end));
    setText('lktEndLeft', weekday(r.end) + ' · ' + fromToday(r.end, today));
    setText('lktDay180', fmt(r.d180));
    setText('lktDue', fmt(r.due));
    setText('lktLength', plural(r.end - close, 'day'));

    var note;
    if (r.due < r.d180) {
      note = 'Your tax return is due before day 180, which cuts the exchange period to ' + plural(r.end - close, 'day') + '. ' +
        (kind === 'apr' || kind === 'mar' ? 'Filing an extension before the due date restores the full 180 days if the extended due date is later.' :
         'The exchange must be completed by that date.');
    } else if (r.end < today) {
      note = 'Both deadlines have passed for this closing date.';
    } else if (r.id45 < today) {
      note = 'The 45-day identification period has ended. You can only acquire property you identified in time, by ' + fmt(r.end) + '.';
    } else {
      note = 'You have the full 180 days. Day 180 comes before your tax return due date, so the return date does not shorten the exchange.';
    }
    if (weekday(r.end) === 'Saturday' || weekday(r.end) === 'Sunday') note += ' Your closing deadline falls on a ' + weekday(r.end) + '; aim to close by the Friday before.';
    setText('lktNote', note);

    var rows = [
      ['Sale closes', close],
      ['45-day identification deadline', r.id45],
      ['Day 180 after closing', r.d180],
      ['Tax return due date', r.due],
      ['Exchange deadline (the earlier of the two above)', r.end]
    ];
    rows.sort(function (a, b) { return a[1] - b[1]; });
    el('lktSchedule').innerHTML = rows.map(function (row) {
      return '<tr><td>' + row[0] + '</td><td>' + fmt(row[1]) + '</td><td>' + weekday(row[1]) + '</td><td>' + (row[1] - close) +
        '</td><td>' + rel(row[1] - today) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var input = el('lktClose');
    if (!input.value) input.value = iso(todayNum());
    var form = el('lktForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
